INSERT INTO wg_people (id,name,kind,tradition,wikidata,years,bio) VALUES ('igor-kufayev','Igor Kufayev','speaker','kashmir-shaivism',NULL,NULL,'Russian-born, Europe-based teacher whose darshans and courses draw heavily on Kashmir Shaivism (Trika, Krama, Spanda) and on kundalini as the process of awakening.');
